   "evidence_ids": [
    "ev-3723edf2d58b"
   ]
  }
 ],
 "ruled_out": [
  {
   "statement": "An error cascade or failing dependency is unlikely: the 5xx ratio was 0.0% avg and max for gateway, orders and inventory.",
   "evidence_ids": [
    "ev-475f30836653",
    "ev-ab523774f133",
    "ev-cf2f8c523735"
   ]
  },
  {
   "statement": "A traffic surge is unlikely: request rates stayed low and stable (about 1.3–2.3 req/s at every service).",
   "evidence_ids": [
